ALTER TABLE public.location_task_orders DROP CONSTRAINT location_task_orders_status_check;ALTER TABLE public.location_task_orders ADD CONSTRAINT location_task_orders_status_check CHECK(status IN('draft','submitted','accepted','rejected'));
CREATE FUNCTION public.resolve_join_agency(p_request uuid,p_person uuid,p_expected_vendor uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record;t record;p record;BEGIN IF auth.uid() IS NULL OR NOT(has_role(auth.uid(),'admin') OR has_role(auth.uid(),'manager')) THEN RAISE EXCEPTION 'Manager access required';END IF;SELECT * INTO r FROM project_join_requests WHERE id=p_request AND status='pending' AND matched_personnel_id=p_person FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Pending matched request required';END IF;SELECT * INTO t FROM project_join_tokens WHERE id=r.token_id;SELECT * INTO p FROM personnel WHERE id=p_person FOR UPDATE;IF t.vendor_id IS NULL OR p.vendor_id IS DISTINCT FROM p_expected_vendor THEN RAISE EXCEPTION 'Agency or worker changed; refresh';END IF;IF EXISTS(SELECT 1 FROM personnel_agency_provenance WHERE personnel_id=p_person AND vendor_id<>t.vendor_id) OR p.employer_customer_id IS NOT NULL THEN RAISE EXCEPTION 'Existing permanent/customer employer cannot be reassigned through a join link';END IF;UPDATE personnel SET vendor_id=t.vendor_id WHERE id=p_person;INSERT INTO audit_logs(user_id,user_email,action_type,resource_type,resource_id,changes_before,changes_after) VALUES(auth.uid(),'agency-resolution','agency_join_resolution','personnel',p_person,jsonb_build_object('vendor_id',p.vendor_id),jsonb_build_object('vendor_id',t.vendor_id,'request_id',p_request));END $$;REVOKE ALL ON FUNCTION public.resolve_join_agency(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.resolve_join_agency(uuid,uuid,uuid) TO authenticated;
CREATE FUNCTION public.delete_location_to_draft(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE loc uuid;BEGIN IF auth.uid() IS NULL OR NOT(has_role(auth.uid(),'admin') OR has_role(auth.uid(),'manager')) THEN RAISE EXCEPTION 'Manager access required';END IF;SELECT location_id INTO loc FROM location_task_orders WHERE id=p_id AND status='draft' FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Only unused drafts can be deleted';END IF;IF EXISTS(SELECT 1 FROM location_to_allocations WHERE task_order_id=p_id) OR EXISTS(SELECT 1 FROM location_to_sheets WHERE task_order_id=p_id) THEN RAISE EXCEPTION 'Used draft cannot be removed';END IF;DELETE FROM location_to_terms WHERE task_order_id=p_id;DELETE FROM location_task_order_lines WHERE task_order_id=p_id;DELETE FROM location_task_orders WHERE id=p_id;INSERT INTO audit_logs(user_id,user_email,action_type,resource_type,resource_id) VALUES(auth.uid(),'to-draft','to_draft_delete','location_task_orders',p_id);END $$;REVOKE ALL ON FUNCTION public.delete_location_to_draft(uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.delete_location_to_draft(uuid) TO authenticated;